 const canvas=document.getElementById('workflow-canvas'),inspector=document.getElementById('node-inspector'),emptyInspector=document.getElementById('inspector-empty'),quickForm=document.getElementById('quick-add-form'),csrf=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content'),typeMeta=@json($stepTypes),employeeTypes=['employee','department_manager','asset_manager','warehouse_manager'];
