 document.querySelectorAll('.approver-type').forEach(select=>select.addEventListener('change',()=>configureApprover(select.closest('form'))));document.querySelectorAll('.employee-reference,.role-reference').forEach(select=>select.addEventListener('change',()=>{const form=select.closest('form'),hidden=form.querySelector('.approver-reference-id');if(!select.classList.contains('d-none'))hidden.value=select.value}));
 function selectNode(node){if(!inspector||!node)return;document.querySelectorAll('.workflow-node.selected').forEach(item=>item.classList.remove('selected'));node.classList.add('selected');inspector.classList.remove('d-none');emptyInspector?.classList.add('d-none');inspector.action=`${inspector.dataset.updateBase}/${node.dataset.stepId}`;document.getElementById('inspector-heading').textContent=node.dataset.name;document.getElementById('inspector-name').value=node.dataset.name||'';document.getElementById('inspector-code').value=node.dataset.code||'';document.getElementById('inspector-type').value=node.dataset.type||'approval';document.getElementById('inspector-due').value=node.dataset.dueHours||'';document.getElementById('inspector-rejection').value=node.dataset.rejection||'terminate';document.getElementById('inspector-description').value=node.dataset.description||'';document.getElementById('inspector-required').checked=node.dataset.required==='1';document.getElementById('inspector-active').checked=node.dataset.active==='1';const icon=document.getElementById('inspector-icon'),meta=typeMeta[node.dataset.type]||typeMeta.condition;icon.className=`node-icon ${meta.class}`;icon.textContent=meta.icon;configureApprover(inspector,node.dataset.approverType,node.dataset.approverReference)}
 document.querySelectorAll('.workflow-node[data-step-id]').forEach(node=>node.addEventListener('click',()=>selectNode(node)));const firstNode=document.querySelector('.workflow-node[data-step-id]');if(firstNode)selectNode(firstNode);
 document.querySelectorAll('.add-step-trigger').forEach(button=>button.addEventListener('click',()=>{quickForm.classList.add('show');document.getElementById('quick-step-type').value=button.dataset.stepType;document.getElementById('quick-add-title').textContent=`افزودن گره «${button.dataset.stepLabel}»`;quickForm.querySelector('[name="name"]').focus()}));document.getElementById('quick-add-close')?.addEventListener('click',()=>quickForm.classList.remove('show'));
 let dragging=null;canvas?.querySelectorAll('.workflow-node[data-step-id]').forEach(node=>{node.addEventListener('dragstart',()=>{dragging=node;node.classList.add('dragging')});node.addEventListener('dragend',()=>{node.classList.remove('dragging');dragging=null});node.addEventListener('dragover',event=>{event.preventDefault();if(!dragging||dragging===node)return;const rect=node.getBoundingClientRect(),before=event.clientX<rect.left+rect.width/2,connector=node.nextElementSibling;if(before)node.before(dragging,dragging.nextElementSibling);else connector.after(dragging,dragging.nextElementSibling)})});canvas?.addEventListener('drop',async event=>{event.preventDefault();const ids=Array.from(canvas.querySelectorAll('.workflow-node[data-step-id]')).map(node=>Number(node.dataset.stepId));if(!ids.length)return;try{const response=await fetch(canvas.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({step_ids:ids})});if(!response.ok)throw new Error();window.location.reload()}catch{alert('ترتیب جدید ذخیره نشد. لطفاً دوباره تلاش کنید.')}})
});
</script>@endif
@endsection
